"""Within-frozen-model C/no-context decision differences, not cross-model mediation."""
from .common import *
from .analysis import summarize

def main():
 p=read('control_positions');keys=['seed','condition','arm','dose','update','position'];a=p[p.control=='Natural-C'].set_index(keys);b=p[p.control=='NoContext'].set_index(keys);assert a.index.equals(b.index);r=a.reset_index()[keys].copy();ac=a.correct.to_numpy(bool);bc=b.correct.to_numpy(bool);r['C_only_error']=(~ac)&bc;r['C_and_baseline_error']=(~ac)&(~bc);r['C_helps_decision']=ac&(~bc);r['both_correct_C_uncertainty_larger']=ac&bc&(a.ce.to_numpy()>b.ce.to_numpy());r['C_minus_baseline_CE']=a.ce.to_numpy()-b.ce.to_numpy();r['C_minus_baseline_margin']=a.margin.to_numpy()-b.margin.to_numpy();r['C_CE']=a.ce.to_numpy();r['baseline_CE']=b.ce.to_numpy();sd=r.groupby(keys[:-1]).agg(C_only_errors=('C_only_error','sum'),shared_errors=('C_and_baseline_error','sum'),C_helped_positions=('C_helps_decision','sum'),C_uncertainty_positions=('both_correct_C_uncertainty_larger','sum'),C_minus_baseline_CE=('C_minus_baseline_CE','mean'),C_minus_baseline_margin=('C_minus_baseline_margin','mean')).reset_index();write_frame(OUT/'tables/C_frozen_position_diagnosis.csv',r);write_frame(OUT/'tables/C_frozen_position_seed.csv',sd);write_frame(OUT/'tables/C_frozen_position_summary.csv',summarize(sd,['condition','arm','dose','update'],['C_only_errors','shared_errors','C_helped_positions','C_uncertainty_positions','C_minus_baseline_CE','C_minus_baseline_margin']));dump(OUT/'audit/position_diagnosis.json',dict(passed=True,rows=len(r),weights_frozen=True,interpretation='within-model input contrast; not training mediation',selection=False))
if __name__=='__main__':main()
